# D31 · Part 1~5 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Python 3.11)
# pip install fastapi==0.165.0 uvicorn==0.54.0 httpx==0.28.1 python-multipart==0.0.34 websockets==17.4 pydantic==2.14.4 numpy==2.4.6 soundfile==0.14.0
# 실행: python d31_flow.py   (서버는 임시 포트로 띄우고 스스로 요청한 뒤 종료 · 인터넷·GPU 불필요)
#   health → TTS(WAV) → STT 업로드(문지기) → 202 작업 접수 → WebSocket 실시간 받아쓰기까지 한 서버로 한 번에
import asyncio
import io
import socket
import threading
import time

import httpx
import numpy as np
import soundfile as sf
import uvicorn
import json

import websockets
from fastapi import BackgroundTasks, FastAPI, File, HTTPException, UploadFile, WebSocket
from fastapi.responses import Response
from pydantic import BaseModel, Field

SR = 16000
WORDS = {"진료": 500.0, "주차": 700.0, "비용": 900.0, "예약": 1100.0}
# 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def say(words, gap: float = 0.15) -> np.ndarray:
    """단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼."""
    t = np.arange(int(0.25 * SR)) / SR
    parts = []
    for w in words:
        parts += [0.4 * np.sin(2 * np.pi * WORDS[w] * t), np.zeros(int(gap * SR))]
    return np.concatenate(parts).astype(np.float32)


def speak(text: str) -> np.ndarray:
    """글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다."""
    return say(sorted((w for w in WORDS if w in text), key=text.find) or ["예약"])


def hear(y: np.ndarray) -> str:
    """소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 센 주파수로 단어를 고른다."""
    n = SR // 50
    loud = [float(np.sqrt(np.mean(y[i:i + n] ** 2))) > 0.05 for i in range(0, len(y) - n + 1, n)]
    words, start = [], None
    for k, v in enumerate(loud + [False]):
        if v and start is None:
            start = k
        elif not v and start is not None:
            seg = y[start * n:k * n]
            f = np.fft.rfftfreq(len(seg), 1 / SR)[int(np.argmax(np.abs(np.fft.rfft(seg))))]
            words.append(min(WORDS, key=lambda w: abs(WORDS[w] - f)))
            start = None
    return " ".join(words)


def wav_bytes(y: np.ndarray) -> bytes:
    buf = io.BytesIO()
    sf.write(buf, np.clip(y, -1, 1), SR, format="WAV", subtype="PCM_16")
    return buf.getvalue()

def start_server(app):
    """임시 포트(0번)를 운영체제에서 받아 uvicorn을 스레드로 띄운다 → (server, thread, 주소)."""
    sock = socket.socket()
    sock.bind(("127.0.0.1", 0))
    sock.listen()
    server = uvicorn.Server(uvicorn.Config(app, log_level="warning"))
    th = threading.Thread(target=server.run, kwargs={"sockets": [sock]}, daemon=True)
    th.start()
    while not server.started:
        time.sleep(0.02)
    return server, th, f"127.0.0.1:{sock.getsockname()[1]}"


def stop_server(server, th) -> bool:
    server.should_exit = True
    th.join(timeout=5)
    return not th.is_alive()

app = FastAPI(title="한빛치과 음성 API(모의)")
SEM = {}
JOBS = {}


class TTSRequest(BaseModel):
    text: str = Field(..., min_length=1, max_length=300)


async def transcribe(y):
    t_q = time.perf_counter()
    async with SEM["s"]:                           # 번호표 1개: 모델은 한 번에 하나
        t0 = time.perf_counter()
        text = await asyncio.to_thread(hear, y)    # 무거운 일은 스레드로
    return text, t0 - t_q, time.perf_counter() - t0


@app.get("/health")
async def health():
    return {"ok": True}


@app.post("/tts")
async def tts_endpoint(req: TTSRequest):
    return Response(content=wav_bytes(speak(req.text)), media_type="audio/wav")


ALLOWED = {"audio/wav", "audio/x-wav", "audio/flac", "audio/ogg"}
MAX_BYTES = 10 * 1024 * 1024                 # 10 MB 넘으면 413


def decode_audio(data: bytes) -> np.ndarray:
    try:
        y, _ = sf.read(io.BytesIO(data), dtype="float32", always_2d=True)
    except Exception:
        raise ValueError("소리로 풀 수 없는 파일")
    return y.mean(axis=1)


@app.post("/stt")
async def stt_endpoint(file: UploadFile = File(...)):
    if file.content_type not in ALLOWED:
        raise HTTPException(status_code=415, detail=f"지원하지 않는 형식: {file.content_type}")
    data = await file.read()
    if len(data) > MAX_BYTES:
        raise HTTPException(status_code=413, detail="파일이 너무 커요")
    try:
        y = decode_audio(data)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    text, waited, worked = await transcribe(y)
    return {"text": text, "wait_sec": round(waited, 3), "stt_sec": round(worked, 3)}


def upload(wav: bytes, ctype: str = "audio/wav", field: str = "file"):
    return {"files": {field: ("v.wav", wav, ctype)}}


async def run_job(job_id, y):
    text, _, _ = await transcribe(y)
    JOBS[job_id] = {"status": "done", "text": text}


@app.post("/jobs/stt", status_code=202)
async def submit_job(background: BackgroundTasks, file: UploadFile = File(...)):
    job_id = f"job-{len(JOBS) + 1:04d}"
    JOBS[job_id] = {"status": "queued"}
    background.add_task(run_job, job_id, decode_audio(await file.read()))
    return {"job_id": job_id, "poll": f"/jobs/{job_id}"}


@app.get("/jobs/{job_id}")
async def get_job(job_id: str):
    if job_id not in JOBS:
        raise HTTPException(status_code=404, detail="없는 작업")
    return JOBS[job_id]


@app.websocket("/ws/stt")
async def ws_stt(ws: WebSocket):
    await ws.accept()
    buf = []
    while True:
        msg = await ws.receive()
        if msg.get("bytes"):
            buf.append(np.frombuffer(msg["bytes"], dtype=np.int16).astype(np.float32) / 32768)
        elif msg.get("text") == "END":
            text, _, _ = await transcribe(np.concatenate(buf))   # 대체 경로: 말 끝 판단(VAD) 대신 END 신호로 끊음
            await ws.send_json({"type": "final", "text": text})
            break
        else:
            break


async def main() -> None:
    server, th, host = start_server(app)
    SEM["s"] = asyncio.Semaphore(1)
    voice = say(["진료", "주차"])
    async with httpx.AsyncClient(base_url=f"http://{host}", timeout=60) as c:
        h = await c.get("/health")
        tts = await c.post("/tts", json={"text": "예약 비용"})
        y_back, _ = sf.read(io.BytesIO(tts.content), dtype="float32")
        stt = await c.post("/stt", **upload(wav_bytes(voice)))
        png = await c.post("/stt", **upload(b"PNG", "image/png"))
        job = await c.post("/jobs/stt", **upload(wav_bytes(voice)))
        for _ in range(100):
            j = (await c.get(job.json()["poll"])).json()
            if j["status"] == "done":
                break
            await asyncio.sleep(0.05)
    async with websockets.connect(f"ws://{host}/ws/stt") as ws:
        pcm = (voice * 32767).astype(np.int16).tobytes()
        for i in range(0, len(pcm), 640):
            await ws.send(pcm[i:i + 640])
        await ws.send("END")
        final = json.loads(await ws.recv())
    print("health", h.status_code, "· tts", tts.status_code, hear(y_back), "· stt", stt.json()["text"], "· 이미지", png.status_code,
          "· 작업", job.status_code, j["text"], "· ws", final["text"])
    check(h.status_code == 200 and tts.headers["content-type"] == "audio/wav" and hear(y_back) == "예약 비용", "TTS가 만든 WAV를 STT가 다시 읽어야 해요.")
    check(stt.json()["text"] == "진료 주차" and png.status_code == 415, "업로드 받아쓰기와 형식 문지기를 확인하세요.")
    check(job.status_code == 202 and j["text"] == "진료 주차" and final["text"] == "진료 주차", "작업 큐와 WebSocket 결과가 같아야 해요.")
    print("서버 종료:", stop_server(server, th))


asyncio.run(main())

flow.typescript:
// D31 · Part 1~5 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d31_flow.ts   (서버는 임시 포트로 띄우고 스스로 요청한 뒤 종료 · 인터넷·GPU 불필요)
//   health → TTS(WAV) → STT 업로드(문지기) → 202 작업 접수 → WebSocket 받아쓰기까지 한 서버로 한 번에
import { createHash } from "node:crypto";
import { createServer } from "node:http";
import type { IncomingMessage, Server, ServerResponse } from "node:http";
import type { AddressInfo } from "node:net";

const SR = 16000;
const WORDS: Record<string, number> = { 진료: 500, 주차: 700, 비용: 900, 예약: 1100 };
// 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function say(words: string[], gap: number = 0.15): Float32Array {
  // 단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼
  const n = Math.floor(0.25 * SR);
  const g = Math.floor(gap * SR);
  const y = new Float32Array(words.length * (n + g));
  words.forEach((w, k) => {
    for (let i = 0; i < n; i++) y[k * (n + g) + i] = 0.4 * Math.sin((2 * Math.PI * WORDS[w] * i) / SR);
  });
  return y;
}

function speak(text: string): Float32Array {
  // 글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다
  const ws = Object.keys(WORDS).filter((w) => text.includes(w)).sort((a, b) => text.indexOf(a) - text.indexOf(b));
  return say(ws.length ? ws : ["예약"]);
}

function nearestWord(seg: Float32Array): string {
  let best = "";
  let bestMag = -1;
  for (const [w, f] of Object.entries(WORDS)) {
    let re = 0;
    let im = 0;
    for (let i = 0; i < seg.length; i++) {
      re += seg[i] * Math.cos((2 * Math.PI * f * i) / SR);
      im += seg[i] * Math.sin((2 * Math.PI * f * i) / SR);
    }
    if (re * re + im * im > bestMag) {
      bestMag = re * re + im * im;
      best = w;
    }
  }
  return best;
}

function hear(y: Float32Array): string {
  // 소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 닮은 주파수의 단어를 고른다
  const n = SR / 50;
  const loud: boolean[] = [];
  for (let i = 0; i + n <= y.length; i += n) {
    let s = 0;
    for (let j = 0; j < n; j++) s += y[i + j] * y[i + j];
    loud.push(Math.sqrt(s / n) > 0.05);
  }
  loud.push(false);
  const words: string[] = [];
  let start = -1;
  loud.forEach((v, k) => {
    if (v && start < 0) start = k;
    else if (!v && start >= 0) {
      words.push(nearestWord(y.subarray(start * n, k * n)));
      start = -1;
    }
  });
  return words.join(" ");
}

function wavBytes(y: Float32Array): Buffer {
  // 16비트 모노 WAV 파일 바이트 (머리 44바이트 + 샘플)
  const b = Buffer.alloc(44 + y.length * 2);
  b.write("RIFF", 0);
  b.writeUInt32LE(36 + y.length * 2, 4);
  b.write("WAVEfmt ", 8);
  b.writeUInt32LE(16, 16);
  b.writeUInt16LE(1, 20);
  b.writeUInt16LE(1, 22);
  b.writeUInt32LE(SR, 24);
  b.writeUInt32LE(SR * 2, 28);
  b.writeUInt16LE(2, 32);
  b.writeUInt16LE(16, 34);
  b.write("data", 36);
  b.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, y[i])) * 32767), 44 + i * 2);
  return b;
}

function decodeWav(buf: Buffer): Float32Array {
  if (buf.length < 44 || buf.toString("latin1", 0, 4) !== "RIFF" || buf.toString("latin1", 8, 12) !== "WAVE") throw new Error("소리로 풀 수 없는 파일");
  const n = (buf.length - 44) >> 1;
  const y = new Float32Array(n);
  for (let i = 0; i < n; i++) y[i] = buf.readInt16LE(44 + i * 2) / 32768;
  return y;
}

function listen(server: Server): Promise<string> {
  // 임시 포트(0번)를 운영체제에서 받아 서버를 띄운다 → "127.0.0.1:포트"
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(`127.0.0.1:${(server.address() as AddressInfo).port}`)));
}

function closeServer(server: Server): Promise<boolean> {
  server.closeAllConnections();
  return new Promise((resolve) => server.close(() => resolve(!server.listening)));
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks);
}

async function readFile(req: IncomingMessage): Promise<{ type: string; data: Buffer } | null> {
  // multipart/form-data에서 'file' 칸 꺼내기 (Node 내장 Response.formData 사용). 없거나 multipart가 아니면 null
  try {
    const form = await new Response(await readBody(req), { headers: { "content-type": req.headers["content-type"] ?? "" } }).formData();
    const f = form.get("file");
    return f instanceof File ? { type: f.type, data: Buffer.from(await f.arrayBuffer()) } : null;
  } catch {
    return null;
  }
}

function uploadForm(wav: Uint8Array, type: string = "audio/wav", field: string = "file"): FormData {
  const form = new FormData();
  form.append(field, new Blob([wav as BlobPart], { type }), "v.wav");
  return form;
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

type WsPeer = { onmessage: ((data: Buffer, isBinary: boolean) => void) | null; send: (data: string | Uint8Array) => void; close: () => void };

function serveWs(server: Server, path: string, handler: (ws: WsPeer) => void): void {
  // Node에는 WebSocket '서버'가 내장돼 있지 않아 HTTP Upgrade(101)와 프레임 읽기 · 쓰기를 직접 구현 (텍스트 · 바이너리만)
  server.on("upgrade", (req, socket) => {
    if (req.url !== path) {
      socket.destroy();
      return;
    }
    const accept = createHash("sha1").update(String(req.headers["sec-websocket-key"]) + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").digest("base64");
    socket.write(`HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${accept}\r\n\r\n`);
    const ws: WsPeer = {
      onmessage: null,
      send(data) {
        const op = typeof data === "string" ? 1 : 2;
        const p = Buffer.from(data);
        const head = p.length < 126 ? Buffer.from([0x80 | op, p.length]) : Buffer.from([0x80 | op, 126, p.length >> 8, p.length & 255]);
        socket.write(Buffer.concat([head, p]));
      },
      close() {
        socket.end(Buffer.from([0x88, 0]));
      },
    };
    let buf = Buffer.alloc(0);
    socket.on("data", (chunk: Buffer) => {
      buf = Buffer.concat([buf, chunk]);
      for (;;) {
        if (buf.length < 2) return;
        const opcode = buf[0] & 15;
        let len = buf[1] & 127;
        let off = 2;
        if (len === 126) {
          if (buf.length < 4) return;
          len = buf.readUInt16BE(2);
          off = 4;
        } else if (len === 127) {
          if (buf.length < 10) return;
          len = Number(buf.readBigUInt64BE(2));
          off = 10;
        }
        if (buf.length < off + 4 + len) return;
        const mask = buf.subarray(off, off + 4);
        const data = Buffer.from(buf.subarray(off + 4, off + 4 + len));
        for (let i = 0; i < len; i++) data[i] ^= mask[i % 4];
        buf = buf.subarray(off + 4 + len);
        if (opcode === 8) {
          socket.end();
          return;
        }
        if (opcode === 1 || opcode === 2) ws.onmessage?.(data, opcode === 2);
      }
    });
    socket.on("error", () => {});
    handler(ws);
  });
}

function wsConnect(host: string, path: string): Promise<WebSocket> {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(`ws://${host}${path}`);
    ws.binaryType = "arraybuffer";
    ws.onopen = () => resolve(ws);
    ws.onerror = () => reject(new Error("WebSocket 연결 실패"));
  });
}

const JOBS: Record<string, { status: string; text?: string }> = {};
let busy: Promise<unknown> = Promise.resolve(); // 번호표 1개: 모델은 한 번에 하나(앞 일이 끝나야 다음 일)

async function transcribe(y: Float32Array): Promise<[string, number, number]> {
  const t0 = performance.now();
  const job = busy.then(async () => {
    await sleep(20); // 무거운 모델 흉내
    return hear(y);
  });
  busy = job.catch(() => undefined);
  const text = await job;
  return [text, (performance.now() - t0) / 1000, 0];
}

const ALLOWED = new Set(["audio/wav", "audio/x-wav", "audio/flac", "audio/ogg"]);
const MAX_BYTES = 10 * 1024 * 1024; // 10 MB 넘으면 413

async function handleStt(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const f = await readFile(req);
  if (!f) return sendJson(res, 422, { detail: "file 칸이 없어요" });
  if (!ALLOWED.has(f.type)) return sendJson(res, 415, { detail: `지원하지 않는 형식: ${f.type}` });
  if (f.data.length > MAX_BYTES) return sendJson(res, 413, { detail: "파일이 너무 커요" });
  let y: Float32Array;
  try {
    y = decodeWav(f.data);
  } catch (e) {
    return sendJson(res, 400, { detail: (e as Error).message });
  }
  const [text, waited, worked] = await transcribe(y);
  sendJson(res, 200, { text, wait_sec: waited, stt_sec: worked });
}

const server = createServer(async (req, res) => {
  if (req.method === "GET" && req.url === "/health") return sendJson(res, 200, { ok: true });
  if (req.method === "POST" && req.url === "/tts") {
    const text = String(JSON.parse((await readBody(req)).toString("utf-8")).text ?? "");
    if (!text) return sendJson(res, 422, { detail: "text가 비었어요" });
    res.writeHead(200, { "content-type": "audio/wav" });
    return res.end(wavBytes(speak(text)));
  }
  if (req.method === "POST" && req.url === "/stt") return handleStt(req, res);
  if (req.method === "POST" && req.url === "/jobs/stt") {
    const f = await readFile(req);
    if (!f) return sendJson(res, 422, { detail: "file 칸이 없어요" });
    const id = `job-${Object.keys(JOBS).length + 1}`;
    JOBS[id] = { status: "queued" };
    transcribe(decodeWav(f.data)).then(([text]) => (JOBS[id] = { status: "done", text }));
    return sendJson(res, 202, { job_id: id, poll: `/jobs/${id}` });
  }
  const m = req.url?.match(/^\/jobs\/([\w-]+)$/);
  if (m) return JOBS[m[1]] ? sendJson(res, 200, JOBS[m[1]]) : sendJson(res, 404, { detail: "없는 작업" });
  sendJson(res, 404, { detail: "없는 주소" });
});

serveWs(server, "/ws/stt", (ws) => {
  const chunks: Buffer[] = [];
  ws.onmessage = async (data, isBinary) => {
    if (isBinary) chunks.push(data);
    else if (data.toString() === "END") {
      const [text] = await transcribe(decodeWav(Buffer.concat([wavBytes(new Float32Array(0)).subarray(0, 44), ...chunks]))); // 대체 경로: 말 끝 판단(VAD) 대신 END 신호로 끊음
      ws.send(JSON.stringify({ type: "final", text }));
      ws.close();
    }
  };
});

async function main(): Promise<void> {
  const host = await listen(server);
  const base = `http://${host}`;
  const voice = say(["진료", "주차"]);
  const h = await fetch(`${base}/health`);
  const tts = await fetch(`${base}/tts`, { method: "POST", body: JSON.stringify({ text: "예약 비용" }) });
  const back = hear(decodeWav(Buffer.from(await tts.arrayBuffer())));
  const stt = (await (await fetch(`${base}/stt`, { method: "POST", body: uploadForm(wavBytes(voice)) })).json()) as { text: string };
  const png = await fetch(`${base}/stt`, { method: "POST", body: uploadForm(Buffer.from("PNG"), "image/png") });
  const job = await fetch(`${base}/jobs/stt`, { method: "POST", body: uploadForm(wavBytes(voice)) });
  const poll = ((await job.json()) as { poll: string }).poll;
  let j: { status: string; text?: string };
  for (;;) {
    j = (await (await fetch(`${base}${poll}`)).json()) as { status: string; text?: string };
    if (j.status === "done") break;
    await sleep(30);
  }
  const ws = await wsConnect(host, "/ws/stt");
  const final = new Promise<{ text: string }>((resolve) => (ws.onmessage = (e) => resolve(JSON.parse(String(e.data)))));
  const pcm = Buffer.alloc(voice.length * 2);
  for (let i = 0; i < voice.length; i++) pcm.writeInt16LE(Math.round(voice[i] * 32767), i * 2);
  for (let i = 0; i < pcm.length; i += 640) ws.send(pcm.subarray(i, i + 640));
  ws.send("END");
  const fin = await final;
  console.log("health", h.status, "· tts", tts.status, back, "· stt", stt.text, "· 이미지", png.status, "· 작업", job.status, j.text, "· ws", fin.text);
  check(h.status === 200 && tts.headers.get("content-type") === "audio/wav" && back === "예약 비용", "TTS가 만든 WAV를 STT가 다시 읽어야 해요.");
  check(stt.text === "진료 주차" && png.status === 415, "업로드 받아쓰기와 형식 문지기를 확인하세요.");
  check(job.status === 202 && j.text === "진료 주차" && fin.text === "진료 주차", "작업 큐와 WebSocket 결과가 같아야 해요.");
  ws.close();
  console.log("서버 종료:", await closeServer(server));
}

main();

http.typescript:
// D31 · Part 1 · 요청 · 응답 · 엔드포인트 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d31_http.ts   (서버는 임시 포트로 띄우고 스스로 요청한 뒤 종료 · 인터넷·GPU 불필요)
//   GET /health · POST /tts(JSON → WAV 바이트) · 형식이 틀리면 422 — 같은 파일 안에서 서버를 띄우고 요청까지
import { createServer } from "node:http";
import type { IncomingMessage, Server, ServerResponse } from "node:http";
import type { AddressInfo } from "node:net";

const SR = 16000;
const WORDS: Record<string, number> = { 진료: 500, 주차: 700, 비용: 900, 예약: 1100 };
// 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function say(words: string[], gap: number = 0.15): Float32Array {
  // 단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼
  const n = Math.floor(0.25 * SR);
  const g = Math.floor(gap * SR);
  const y = new Float32Array(words.length * (n + g));
  words.forEach((w, k) => {
    for (let i = 0; i < n; i++) y[k * (n + g) + i] = 0.4 * Math.sin((2 * Math.PI * WORDS[w] * i) / SR);
  });
  return y;
}

function speak(text: string): Float32Array {
  // 글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다
  const ws = Object.keys(WORDS).filter((w) => text.includes(w)).sort((a, b) => text.indexOf(a) - text.indexOf(b));
  return say(ws.length ? ws : ["예약"]);
}

function nearestWord(seg: Float32Array): string {
  let best = "";
  let bestMag = -1;
  for (const [w, f] of Object.entries(WORDS)) {
    let re = 0;
    let im = 0;
    for (let i = 0; i < seg.length; i++) {
      re += seg[i] * Math.cos((2 * Math.PI * f * i) / SR);
      im += seg[i] * Math.sin((2 * Math.PI * f * i) / SR);
    }
    if (re * re + im * im > bestMag) {
      bestMag = re * re + im * im;
      best = w;
    }
  }
  return best;
}

function hear(y: Float32Array): string {
  // 소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 닮은 주파수의 단어를 고른다
  const n = SR / 50;
  const loud: boolean[] = [];
  for (let i = 0; i + n <= y.length; i += n) {
    let s = 0;
    for (let j = 0; j < n; j++) s += y[i + j] * y[i + j];
    loud.push(Math.sqrt(s / n) > 0.05);
  }
  loud.push(false);
  const words: string[] = [];
  let start = -1;
  loud.forEach((v, k) => {
    if (v && start < 0) start = k;
    else if (!v && start >= 0) {
      words.push(nearestWord(y.subarray(start * n, k * n)));
      start = -1;
    }
  });
  return words.join(" ");
}

function wavBytes(y: Float32Array): Buffer {
  // 16비트 모노 WAV 파일 바이트 (머리 44바이트 + 샘플)
  const b = Buffer.alloc(44 + y.length * 2);
  b.write("RIFF", 0);
  b.writeUInt32LE(36 + y.length * 2, 4);
  b.write("WAVEfmt ", 8);
  b.writeUInt32LE(16, 16);
  b.writeUInt16LE(1, 20);
  b.writeUInt16LE(1, 22);
  b.writeUInt32LE(SR, 24);
  b.writeUInt32LE(SR * 2, 28);
  b.writeUInt16LE(2, 32);
  b.writeUInt16LE(16, 34);
  b.write("data", 36);
  b.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, y[i])) * 32767), 44 + i * 2);
  return b;
}

function decodeWav(buf: Buffer): Float32Array {
  if (buf.length < 44 || buf.toString("latin1", 0, 4) !== "RIFF" || buf.toString("latin1", 8, 12) !== "WAVE") throw new Error("소리로 풀 수 없는 파일");
  const n = (buf.length - 44) >> 1;
  const y = new Float32Array(n);
  for (let i = 0; i < n; i++) y[i] = buf.readInt16LE(44 + i * 2) / 32768;
  return y;
}

function listen(server: Server): Promise<string> {
  // 임시 포트(0번)를 운영체제에서 받아 서버를 띄운다 → "127.0.0.1:포트"
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(`127.0.0.1:${(server.address() as AddressInfo).port}`)));
}

function closeServer(server: Server): Promise<boolean> {
  server.closeAllConnections();
  return new Promise((resolve) => server.close(() => resolve(!server.listening)));
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks);
}

async function readFile(req: IncomingMessage): Promise<{ type: string; data: Buffer } | null> {
  // multipart/form-data에서 'file' 칸 꺼내기 (Node 내장 Response.formData 사용). 없거나 multipart가 아니면 null
  try {
    const form = await new Response(await readBody(req), { headers: { "content-type": req.headers["content-type"] ?? "" } }).formData();
    const f = form.get("file");
    return f instanceof File ? { type: f.type, data: Buffer.from(await f.arrayBuffer()) } : null;
  } catch {
    return null;
  }
}

function uploadForm(wav: Uint8Array, type: string = "audio/wav", field: string = "file"): FormData {
  const form = new FormData();
  form.append(field, new Blob([wav as BlobPart], { type }), "v.wav");
  return form;
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

const server = createServer(async (req, res) => {
  if (req.method === "GET" && req.url === "/health") return sendJson(res, 200, { ok: true }); // '읽기' 요청(GET)
  if (req.method === "POST" && req.url === "/tts") {
    let text: unknown;
    try {
      text = JSON.parse((await readBody(req)).toString("utf-8")).text;
    } catch {
      text = undefined;
    }
    if (typeof text !== "string" || text.length < 1 || text.length > 300) return sendJson(res, 422, { detail: "text는 1~300자 글자여야 해요" }); // 모양 검사
    const y = speak(text);
    res.writeHead(200, { "content-type": "audio/wav", "x-audio-seconds": (y.length / SR).toFixed(2) });
    return res.end(wavBytes(y));
  }
  sendJson(res, 404, { detail: "없는 주소" });
});

async function main(): Promise<void> {
  const host = await listen(server);
  console.log("임시 포트로 시작:", host);
  const r = await fetch(`http://${host}/health`);
  const body = (await r.json()) as { ok: boolean };
  console.log("GET /health →", r.status, body);
  check(r.status === 200 && body.ok === true, "GET 요청은 200과 JSON을 돌려줘야 해요.");

  const t = await fetch(`http://${host}/tts`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ text: "진료 시간과 주차 알려 주세요" }) });
  const wav = Buffer.from(await t.arrayBuffer());
  const y = decodeWav(wav);
  console.log("POST /tts →", t.status, t.headers.get("content-type"), `${wav.length.toLocaleString()}바이트 · ${(y.length / SR).toFixed(2)}초`);
  check(t.status === 200 && t.headers.get("content-type") === "audio/wav" && hear(y) === "진료 주차", "WAV 바이트와 audio/wav 형식을 확인하세요.");

  const bad = await fetch(`http://${host}/tts`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ text: "" }) });
  console.log("빈 글자 요청 →", bad.status, ((await bad.json()) as { detail: string }).detail);
  check(bad.status === 422, "형식이 틀린 요청은 422로 거절돼요.");
  console.log("서버 종료:", await closeServer(server));
}

main();

upload.python:
# D31 · Part 2 · 파일 업로드 문지기 — 단독 실행 완성 코드 (Python 3.11)
# pip install fastapi==0.165.0 uvicorn==0.54.0 httpx==0.28.1 python-multipart==0.0.34 websockets==17.4 pydantic==2.14.4 numpy==2.4.6 soundfile==0.14.0
# 실행: python d31_upload.py   (서버는 임시 포트로 띄우고 스스로 요청한 뒤 종료 · 인터넷·GPU 불필요)
#   POST /stt: UploadFile을 받아 형식(415) · 크기(413) · 깨진 파일(400) · 칸 이름(422)을 차례로 검사
import asyncio
import io
import socket
import threading
import time

import httpx
import numpy as np
import soundfile as sf
import uvicorn
from fastapi import FastAPI, File, HTTPException, UploadFile

SR = 16000
WORDS = {"진료": 500.0, "주차": 700.0, "비용": 900.0, "예약": 1100.0}
# 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def say(words, gap: float = 0.15) -> np.ndarray:
    """단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼."""
    t = np.arange(int(0.25 * SR)) / SR
    parts = []
    for w in words:
        parts += [0.4 * np.sin(2 * np.pi * WORDS[w] * t), np.zeros(int(gap * SR))]
    return np.concatenate(parts).astype(np.float32)


def speak(text: str) -> np.ndarray:
    """글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다."""
    return say(sorted((w for w in WORDS if w in text), key=text.find) or ["예약"])


def hear(y: np.ndarray) -> str:
    """소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 센 주파수로 단어를 고른다."""
    n = SR // 50
    loud = [float(np.sqrt(np.mean(y[i:i + n] ** 2))) > 0.05 for i in range(0, len(y) - n + 1, n)]
    words, start = [], None
    for k, v in enumerate(loud + [False]):
        if v and start is None:
            start = k
        elif not v and start is not None:
            seg = y[start * n:k * n]
            f = np.fft.rfftfreq(len(seg), 1 / SR)[int(np.argmax(np.abs(np.fft.rfft(seg))))]
            words.append(min(WORDS, key=lambda w: abs(WORDS[w] - f)))
            start = None
    return " ".join(words)


def wav_bytes(y: np.ndarray) -> bytes:
    buf = io.BytesIO()
    sf.write(buf, np.clip(y, -1, 1), SR, format="WAV", subtype="PCM_16")
    return buf.getvalue()

def start_server(app):
    """임시 포트(0번)를 운영체제에서 받아 uvicorn을 스레드로 띄운다 → (server, thread, 주소)."""
    sock = socket.socket()
    sock.bind(("127.0.0.1", 0))
    sock.listen()
    server = uvicorn.Server(uvicorn.Config(app, log_level="warning"))
    th = threading.Thread(target=server.run, kwargs={"sockets": [sock]}, daemon=True)
    th.start()
    while not server.started:
        time.sleep(0.02)
    return server, th, f"127.0.0.1:{sock.getsockname()[1]}"


def stop_server(server, th) -> bool:
    server.should_exit = True
    th.join(timeout=5)
    return not th.is_alive()

app = FastAPI(title="한빛치과 음성 API(모의)")


async def transcribe(y):                           # 받아쓰기(모의): 주파수로 단어 고르기
    t0 = time.perf_counter()
    return hear(y), 0.0, time.perf_counter() - t0


ALLOWED = {"audio/wav", "audio/x-wav", "audio/flac", "audio/ogg"}
MAX_BYTES = 10 * 1024 * 1024                 # 10 MB 넘으면 413


def decode_audio(data: bytes) -> np.ndarray:
    try:
        y, _ = sf.read(io.BytesIO(data), dtype="float32", always_2d=True)
    except Exception:
        raise ValueError("소리로 풀 수 없는 파일")
    return y.mean(axis=1)


@app.post("/stt")
async def stt_endpoint(file: UploadFile = File(...)):
    if file.content_type not in ALLOWED:
        raise HTTPException(status_code=415, detail=f"지원하지 않는 형식: {file.content_type}")
    data = await file.read()
    if len(data) > MAX_BYTES:
        raise HTTPException(status_code=413, detail="파일이 너무 커요")
    try:
        y = decode_audio(data)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    text, waited, worked = await transcribe(y)
    return {"text": text, "wait_sec": round(waited, 3), "stt_sec": round(worked, 3)}


def upload(wav: bytes, ctype: str = "audio/wav", field: str = "file"):
    return {"files": {field: ("v.wav", wav, ctype)}}


async def main() -> None:
    server, th, host = start_server(app)
    voice = wav_bytes(say(["진료", "비용"]))
    cases = [
        ("정상 WAV", upload(voice), 200),
        ("이미지 파일", upload(b"\x89PNG....", "image/png"), 415),
        ("11 MB WAV", upload(b"\0" * (11 * 1024 * 1024)), 413),
        ("깨진 WAV", upload(b"RIFF1234WAVEjunk"), 400),
        ("파일 칸 이름이 틀림", upload(voice, field="audio"), 422),
    ]
    got = {}
    async with httpx.AsyncClient(base_url=f"http://{host}", timeout=60) as client:
        for label, kw, want in cases:
            r = await client.post("/stt", **kw)
            got[label] = r.status_code
            body = r.json()
            print(f"{label:<14} → {r.status_code} (기대 {want}) {str(body.get('text') or body.get('detail'))[:50]}")
        ok = await client.post("/stt", **upload(voice))
    check(ok.json()["text"] == "진료 비용", "정상 파일은 받아쓰기 결과가 JSON으로 와야 해요.")
    check(all(got[label] == want for label, _, want in cases), "문지기 검사마다 상태 코드가 달라야 해요.")
    print("서버 종료:", stop_server(server, th))


asyncio.run(main())

