  const voice = wavBytes(say(["예약"]));
  const post = (path: string, body?: FormData) => fetch(`http://${host}${path}`, { method: "POST", body });
  const seen: Record<number, string> = {};
  const runs: [string, Response][] = [
    ["정상 받아쓰기", await post("/stt", uploadForm(voice))],
    ["긴 파일 접수", await post("/jobs/stt", uploadForm(voice))],
    ["깨진 소리 파일", await post("/stt", uploadForm(Buffer.from("RIFFjunk")))],
    ["없는 작업 조회", await fetch(`http://${host}/jobs/job-9999`)],
    ["11 MB 파일", await post("/stt", uploadForm(Buffer.alloc(11 << 20)))],
    ["이미지 파일", await post("/stt", uploadForm(Buffer.from("PNG"), "image/png"))],
