loop.typescript:
// D31 · Part 3 · 이벤트 루프가 막히는 순간 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d31_loop.ts   (서버는 임시 포트로 띄우고 스스로 요청한 뒤 종료 · 인터넷·GPU 불필요)
//   Node도 한 줄 일꾼(이벤트 루프): 요청 처리 중 오래 걸리는 일을 직접 하면 모두 멈춤 → Worker 스레드로 보내면 계속 응답
import { Worker } from "node:worker_threads";
import { createServer } from "node:http";
import type { IncomingMessage, Server, ServerResponse } from "node:http";
import type { AddressInfo } from "node:net";

const SR = 16000;
const WORDS: Record<string, number> = { 진료: 500, 주차: 700, 비용: 900, 예약: 1100 };
// 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function say(words: string[], gap: number = 0.15): Float32Array {
  // 단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼
  const n = Math.floor(0.25 * SR);
  const g = Math.floor(gap * SR);
  const y = new Float32Array(words.length * (n + g));
  words.forEach((w, k) => {
    for (let i = 0; i < n; i++) y[k * (n + g) + i] = 0.4 * Math.sin((2 * Math.PI * WORDS[w] * i) / SR);
  });
  return y;
}

function speak(text: string): Float32Array {
  // 글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다
  const ws = Object.keys(WORDS).filter((w) => text.includes(w)).sort((a, b) => text.indexOf(a) - text.indexOf(b));
  return say(ws.length ? ws : ["예약"]);
}

function nearestWord(seg: Float32Array): string {
  let best = "";
  let bestMag = -1;
  for (const [w, f] of Object.entries(WORDS)) {
    let re = 0;
    let im = 0;
    for (let i = 0; i < seg.length; i++) {
      re += seg[i] * Math.cos((2 * Math.PI * f * i) / SR);
      im += seg[i] * Math.sin((2 * Math.PI * f * i) / SR);
    }
    if (re * re + im * im > bestMag) {
      bestMag = re * re + im * im;
      best = w;
    }
  }
  return best;
}

function hear(y: Float32Array): string {
  // 소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 닮은 주파수의 단어를 고른다
  const n = SR / 50;
  const loud: boolean[] = [];
  for (let i = 0; i + n <= y.length; i += n) {
    let s = 0;
    for (let j = 0; j < n; j++) s += y[i + j] * y[i + j];
    loud.push(Math.sqrt(s / n) > 0.05);
  }
  loud.push(false);
  const words: string[] = [];
  let start = -1;
  loud.forEach((v, k) => {
    if (v && start < 0) start = k;
    else if (!v && start >= 0) {
      words.push(nearestWord(y.subarray(start * n, k * n)));
      start = -1;
    }
  });
  return words.join(" ");
}

function wavBytes(y: Float32Array): Buffer {
  // 16비트 모노 WAV 파일 바이트 (머리 44바이트 + 샘플)
  const b = Buffer.alloc(44 + y.length * 2);
  b.write("RIFF", 0);
  b.writeUInt32LE(36 + y.length * 2, 4);
  b.write("WAVEfmt ", 8);
  b.writeUInt32LE(16, 16);
  b.writeUInt16LE(1, 20);
  b.writeUInt16LE(1, 22);
  b.writeUInt32LE(SR, 24);
  b.writeUInt32LE(SR * 2, 28);
  b.writeUInt16LE(2, 32);
  b.writeUInt16LE(16, 34);
  b.write("data", 36);
  b.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, y[i])) * 32767), 44 + i * 2);
  return b;
}

function decodeWav(buf: Buffer): Float32Array {
  if (buf.length < 44 || buf.toString("latin1", 0, 4) !== "RIFF" || buf.toString("latin1", 8, 12) !== "WAVE") throw new Error("소리로 풀 수 없는 파일");
  const n = (buf.length - 44) >> 1;
  const y = new Float32Array(n);
  for (let i = 0; i < n; i++) y[i] = buf.readInt16LE(44 + i * 2) / 32768;
  return y;
}

function listen(server: Server): Promise<string> {
  // 임시 포트(0번)를 운영체제에서 받아 서버를 띄운다 → "127.0.0.1:포트"
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(`127.0.0.1:${(server.address() as AddressInfo).port}`)));
}

function closeServer(server: Server): Promise<boolean> {
  server.closeAllConnections();
  return new Promise((resolve) => server.close(() => resolve(!server.listening)));
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks);
}

async function readFile(req: IncomingMessage): Promise<{ type: string; data: Buffer } | null> {
  // multipart/form-data에서 'file' 칸 꺼내기 (Node 내장 Response.formData 사용). 없거나 multipart가 아니면 null
  try {
    const form = await new Response(await readBody(req), { headers: { "content-type": req.headers["content-type"] ?? "" } }).formData();
    const f = form.get("file");
    return f instanceof File ? { type: f.type, data: Buffer.from(await f.arrayBuffer()) } : null;
  } catch {
    return null;
  }
}

function uploadForm(wav: Uint8Array, type: string = "audio/wav", field: string = "file"): FormData {
  const form = new FormData();
  form.append(field, new Blob([wav as BlobPart], { type }), "v.wav");
  return form;
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

const MODE = { fixed: false };

function blockingWork(ms: number): void {
  // 무거운 모델 흉내: ms 동안 이 스레드를 붙잡는 일 (Atomics.wait = 잠들지만 다른 일은 못 함)
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

function workInThread(ms: number): Promise<void> {
  // 같은 일을 다른 스레드에서 → 파이썬의 asyncio.to_thread 와 같은 역할
  return new Promise((resolve, reject) => {
    const w = new Worker(`Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ${ms});`, { eval: true });
    w.on("exit", () => resolve());
    w.on("error", reject);
  });
}

const server = createServer(async (req, res) => {
  if (req.url === "/health") return sendJson(res, 200, { ok: true });
  if (req.url === "/stt-demo") {
    const y = say(["진료"]);
    if (MODE.fixed) await workInThread(300);
    else blockingWork(300); // 루프 위에서 그냥 실행 → 모두가 기다림
    return sendJson(res, 200, { text: hear(y) });
  }
  sendJson(res, 404, { detail: "없는 주소" });
});

async function stress(host: string): Promise<number> {
  // STT 3건을 동시에 보내는 동안, 20 ms마다 울리는 타이머가 얼마나 늦게 불렸는지(이벤트 루프 멈춤) 중 최댓값(초)
  let last = performance.now();
  let worst = 0;
  const tick = setInterval(() => {
    const now = performance.now();
    worst = Math.max(worst, now - last - 20);
    last = now;
  }, 20);
  await sleep(100);
  const rs = await Promise.all([1, 2, 3].map(() => fetch(`http://${host}/stt-demo`).then((r) => r.json() as Promise<{ text: string }>)));
  await sleep(50);
  clearInterval(tick);
  if (!rs.every((r) => r.text === "진료")) throw new Error("받아쓰기 결과가 달라요");
  return worst / 1000;
}

async function main(): Promise<void> {
  const host = await listen(server);
  const before = await stress(host);
  MODE.fixed = true;
  const after = await stress(host);
  console.log(`루프가 멈춘 가장 긴 시간: 막힘 ${(before * 1000).toFixed(0)} ms → Worker 스레드로 보낸 뒤 ${(after * 1000).toFixed(0)} ms`);
  check(before > 0.25, "요청 처리 중 직접 오래 일하면 이벤트 루프가 멈춰야 해요.");
  check(after < 0.25 && after < before / 2, "Worker 스레드로 보내면 루프가 계속 돌아야 해요.");
  console.log("서버 종료:", await closeServer(server));
}

main();

