function listen(server: Server): Promise<string> {
  // 임시 포트(0번)를 운영체제에서 받아 서버를 띄운다 → "127.0.0.1:포트"
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(`127.0.0.1:${(server.address() as AddressInfo).port}`)));
}

function closeServer(server: Server): Promise<boolean> {
  server.closeAllConnections();
  return new Promise((resolve) => server.close(() => resolve(!server.listening)));
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks);
}

async function readFile(req: IncomingMessage): Promise<{ type: string; data: Buffer } | null> {
  // multipart/form-data에서 'file' 칸 꺼내기 (Node 내장 Response.formData 사용). 없거나 multipart가 아니면 null
  try {
    const form = await new Response(await readBody(req), { headers: { "content-type": req.headers["content-type"] ?? "" } }).formData();
    const f = form.get("file");
    return f instanceof File ? { type: f.type, data: Buffer.from(await f.arrayBuffer()) } : null;
  } catch {
    return null;
  }
}

function uploadForm(wav: Uint8Array, type: string = "audio/wav", field: string = "file"): FormData {
  const form = new FormData();
  form.append(field, new Blob([wav as BlobPart], { type }), "v.wav");
  return form;
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

class Semaphore {
  // 번호표: 동시에 들어갈 수 limit. 가득 차면 차례를 기다린다
  limit: number;
  used: number = 0;
  waiting: (() => void)[] = [];
  constructor(limit: number) {
    this.limit = limit;
  }
  async acquire(): Promise<void> {
    if (this.used < this.limit) {
      this.used++;
      return;
    }
    await new Promise<void>((resolve) => this.waiting.push(resolve)); // 깨워 줄 때 자리를 물려받음
  }
  release(): void {
    const next = this.waiting.shift();
    if (next) next();
    else this.used--;
  }
}

const active = { now: 0, max: 0 };
let sem = new Semaphore(1);
const JOBS: Record<string, { status: string; text?: string }> = {};

async function heavyStt(y: Float32Array): Promise<string> {
  // 모델 흉내: 0.15초 걸리고, 동시에 몇 개가 들어왔는지 센다
  active.now++;
  active.max = Math.max(active.max, active.now);
  await sleep(150);
  active.now--;
  return hear(y);
}

async function transcribe(y: Float32Array): Promise<[string, number]> {
  const tq = performance.now();
  await sem.acquire(); // 차례가 올 때까지 기다림(await) → 그동안 루프는 다른 요청 처리
  const wait = (performance.now() - tq) / 1000;
  try {
    return [await heavyStt(y), wait];
  } finally {
    sem.release();
  }
}

const server = createServer(async (req, res) => {
  if (req.method === "POST" && req.url === "/stt") {
    const f = await readFile(req);
    if (!f) return sendJson(res, 422, { detail: "file 칸이 없어요" });
    const [text, wait] = await transcribe(decodeWav(f.data));
    return sendJson(res, 200, { text, wait_sec: wait });
  }
  if (req.method === "POST" && req.url === "/jobs/stt") {
    const f = await readFile(req);
    if (!f) return sendJson(res, 422, { detail: "file 칸이 없어요" });
    const id = `job-${Object.keys(JOBS).length + 1}`;
    JOBS[id] = { status: "queued" };
    transcribe(decodeWav(f.data)).then(([text]) => (JOBS[id] = { status: "done", text })); // 응답을 보낸 '뒤에' 실행
    JOBS[id].status = "running";
    return sendJson(res, 202, { job_id: id, poll: `/jobs/${id}` });
  }
  const m = req.url?.match(/^\/jobs\/([\w-]+)$/);
  if (m) return JOBS[m[1]] ? sendJson(res, 200, { job_id: m[1], ...JOBS[m[1]] }) : sendJson(res, 404, { detail: "없는 작업" });
  sendJson(res, 404, { detail: "없는 주소" });
});

async function burst(host: string, slots: number): Promise<[number, number]> {
  sem = new Semaphore(slots);
  active.max = 0;
  const wav = wavBytes(say(["주차"]));
  const rs = await Promise.all([1, 2, 3].map(() => fetch(`http://${host}/stt`, { method: "POST", body: uploadForm(wav) }).then((r) => r.json() as Promise<{ wait_sec: number }>)));
  return [active.max, rs.reduce((a, r) => a + r.wait_sec, 0)];
}

async function main(): Promise<void> {
  const host = await listen(server);
  const [one, wait1] = await burst(host, 1);
  const [three, wait3] = await burst(host, 3);
  console.log(`Semaphore(1): 동시 처리 최대 ${one}건 · 줄 선 시간 합 ${wait1.toFixed(2)}초`);
  console.log(`Semaphore(3): 동시 처리 최대 ${three}건 · 줄 선 시간 합 ${wait3.toFixed(2)}초`);
  check(one === 1 && wait1 > 0.2, "번호표가 1이면 한 번에 하나만 처리하고 나머지는 줄을 서요.");
  check(three >= 2 && wait3 < wait1, "번호표를 늘리면 동시에 더 처리해요.");

  sem = new Semaphore(1);
  const t0 = performance.now();
  const r = await fetch(`http://${host}/jobs/stt`, { method: "POST", body: uploadForm(wavBytes(say(["예약", "비용"]))) });
  const quick = (performance.now() - t0) / 1000;
  const ticket = (await r.json()) as { poll: string };
  const states: string[] = [];
  let j: { status: string; text?: string };
  for (;;) {
    j = (await (await fetch(`http://${host}${ticket.poll}`)).json()) as { status: string; text?: string };
    states.push(j.status);
    if (j.status === "done") break;
    await sleep(50);
  }
  console.log(`접수 → ${r.status} ${JSON.stringify(ticket)} (${quick.toFixed(2)}초 만에 응답) · 상태 변화 ${[...new Set(states)].join(" → ")} · 결과 ${j.text}`);
  check(r.status === 202 && j.text === "예약 비용", "접수(202) 뒤 조회하면 결과가 나와야 해요.");
  console.log("서버 종료:", await closeServer(server));
}

main();

ws.typescript:
// D31 · Part 4 · WebSocket 실시간 받아쓰기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d31_ws.ts   (서버는 임시 포트로 띄우고 스스로 요청한 뒤 종료 · 인터넷·GPU 불필요)
//   20 ms PCM16 조각을 한 연결로 계속 보내면 서버가 에너지 VAD로 말 시작 · 끝을 찾아 받아쓰기(final)를 돌려줌
import { createHash } from "node:crypto";
import { createServer } from "node:http";
import type { IncomingMessage, Server, ServerResponse } from "node:http";
import type { AddressInfo } from "node:net";

const SR = 16000;
const WORDS: Record<string, number> = { 진료: 500, 주차: 700, 비용: 900, 예약: 1100 };
// 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function say(words: string[], gap: number = 0.15): Float32Array {
  // 단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼
  const n = Math.floor(0.25 * SR);
  const g = Math.floor(gap * SR);
  const y = new Float32Array(words.length * (n + g));
  words.forEach((w, k) => {
    for (let i = 0; i < n; i++) y[k * (n + g) + i] = 0.4 * Math.sin((2 * Math.PI * WORDS[w] * i) / SR);
  });
  return y;
}

function speak(text: string): Float32Array {
  // 글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다
  const ws = Object.keys(WORDS).filter((w) => text.includes(w)).sort((a, b) => text.indexOf(a) - text.indexOf(b));
  return say(ws.length ? ws : ["예약"]);
}

function nearestWord(seg: Float32Array): string {
  let best = "";
  let bestMag = -1;
  for (const [w, f] of Object.entries(WORDS)) {
    let re = 0;
    let im = 0;
    for (let i = 0; i < seg.length; i++) {
      re += seg[i] * Math.cos((2 * Math.PI * f * i) / SR);
      im += seg[i] * Math.sin((2 * Math.PI * f * i) / SR);
    }
    if (re * re + im * im > bestMag) {
      bestMag = re * re + im * im;
      best = w;
    }
  }
  return best;
}

function hear(y: Float32Array): string {
  // 소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 닮은 주파수의 단어를 고른다
  const n = SR / 50;
  const loud: boolean[] = [];
  for (let i = 0; i + n <= y.length; i += n) {
    let s = 0;
    for (let j = 0; j < n; j++) s += y[i + j] * y[i + j];
    loud.push(Math.sqrt(s / n) > 0.05);
  }
  loud.push(false);
  const words: string[] = [];
  let start = -1;
  loud.forEach((v, k) => {
    if (v && start < 0) start = k;
    else if (!v && start >= 0) {
      words.push(nearestWord(y.subarray(start * n, k * n)));
      start = -1;
    }
  });
  return words.join(" ");
}

function wavBytes(y: Float32Array): Buffer {
  // 16비트 모노 WAV 파일 바이트 (머리 44바이트 + 샘플)
  const b = Buffer.alloc(44 + y.length * 2);
  b.write("RIFF", 0);
  b.writeUInt32LE(36 + y.length * 2, 4);
  b.write("WAVEfmt ", 8);
  b.writeUInt32LE(16, 16);
  b.writeUInt16LE(1, 20);
  b.writeUInt16LE(1, 22);
  b.writeUInt32LE(SR, 24);
  b.writeUInt32LE(SR * 2, 28);
  b.writeUInt16LE(2, 32);
  b.writeUInt16LE(16, 34);
  b.write("data", 36);
  b.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, y[i])) * 32767), 44 + i * 2);
  return b;
}

function decodeWav(buf: Buffer): Float32Array {
  if (buf.length < 44 || buf.toString("latin1", 0, 4) !== "RIFF" || buf.toString("latin1", 8, 12) !== "WAVE") throw new Error("소리로 풀 수 없는 파일");
  const n = (buf.length - 44) >> 1;
  const y = new Float32Array(n);
  for (let i = 0; i < n; i++) y[i] = buf.readInt16LE(44 + i * 2) / 32768;
  return y;
}

function listen(server: Server): Promise<string> {
  // 임시 포트(0번)를 운영체제에서 받아 서버를 띄운다 → "127.0.0.1:포트"
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(`127.0.0.1:${(server.address() as AddressInfo).port}`)));
}

function closeServer(server: Server): Promise<boolean> {
  server.closeAllConnections();
  return new Promise((resolve) => server.close(() => resolve(!server.listening)));
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks);
}

async function readFile(req: IncomingMessage): Promise<{ type: string; data: Buffer } | null> {
  // multipart/form-data에서 'file' 칸 꺼내기 (Node 내장 Response.formData 사용). 없거나 multipart가 아니면 null
  try {
    const form = await new Response(await readBody(req), { headers: { "content-type": req.headers["content-type"] ?? "" } }).formData();
    const f = form.get("file");
    return f instanceof File ? { type: f.type, data: Buffer.from(await f.arrayBuffer()) } : null;
  } catch {
    return null;
  }
}

function uploadForm(wav: Uint8Array, type: string = "audio/wav", field: string = "file"): FormData {
  const form = new FormData();
  form.append(field, new Blob([wav as BlobPart], { type }), "v.wav");
  return form;
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

type WsPeer = { onmessage: ((data: Buffer, isBinary: boolean) => void) | null; send: (data: string | Uint8Array) => void; close: () => void };

function serveWs(server: Server, path: string, handler: (ws: WsPeer) => void): void {
  // Node에는 WebSocket '서버'가 내장돼 있지 않아 HTTP Upgrade(101)와 프레임 읽기 · 쓰기를 직접 구현 (텍스트 · 바이너리만)
  server.on("upgrade", (req, socket) => {
    if (req.url !== path) {
      socket.destroy();
      return;
    }
    const accept = createHash("sha1").update(String(req.headers["sec-websocket-key"]) + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").digest("base64");
    socket.write(`HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${accept}\r\n\r\n`);
    const ws: WsPeer = {
      onmessage: null,
      send(data) {
        const op = typeof data === "string" ? 1 : 2;
        const p = Buffer.from(data);
        const head = p.length < 126 ? Buffer.from([0x80 | op, p.length]) : Buffer.from([0x80 | op, 126, p.length >> 8, p.length & 255]);
        socket.write(Buffer.concat([head, p]));
      },
      close() {
        socket.end(Buffer.from([0x88, 0]));
      },
    };
    let buf = Buffer.alloc(0);
    socket.on("data", (chunk: Buffer) => {
      buf = Buffer.concat([buf, chunk]);
      for (;;) {
        if (buf.length < 2) return;
        const opcode = buf[0] & 15;
        let len = buf[1] & 127;
        let off = 2;
        if (len === 126) {
          if (buf.length < 4) return;
          len = buf.readUInt16BE(2);
          off = 4;
        } else if (len === 127) {
          if (buf.length < 10) return;
          len = Number(buf.readBigUInt64BE(2));
          off = 10;
        }
        if (buf.length < off + 4 + len) return;
        const mask = buf.subarray(off, off + 4);
        const data = Buffer.from(buf.subarray(off + 4, off + 4 + len));
        for (let i = 0; i < len; i++) data[i] ^= mask[i % 4];
        buf = buf.subarray(off + 4 + len);
        if (opcode === 8) {
          socket.end();
          return;
        }
        if (opcode === 1 || opcode === 2) ws.onmessage?.(data, opcode === 2);
      }
    });
    socket.on("error", () => {});
    handler(ws);
  });
}

function wsConnect(host: string, path: string): Promise<WebSocket> {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(`ws://${host}${path}`);
    ws.binaryType = "arraybuffer";
    ws.onopen = () => resolve(ws);
    ws.onerror = () => reject(new Error("WebSocket 연결 실패"));
  });
}

const FRAME = SR / 50; // 20 ms = 320 샘플 = 640 바이트
const THRESH_DB = -38;
const HANG_SEC = 0.6; // 말 끝 기다림
const MIN_SPEECH = 0.25; // 너무 짧은 소리 무시

class Endpointer {
  // 20 ms 조각을 받아 '말 시작 · 끝'을 찾는 에너지 VAD
  t: number = 0;
  inSpeech: boolean = false;
  quiet: number = 0;
  buf: Float32Array[] = [];
  feed(pcm16: Buffer): [string, number, Float32Array | null][] {
    const n = pcm16.length >> 1;
    const x = new Float32Array(n);
    let s = 0;
    for (let i = 0; i < n; i++) {
      x[i] = pcm16.readInt16LE(i * 2) / 32768;
      s += x[i] * x[i];
    }
    const db = 20 * Math.log10(Math.sqrt(s / n) + 1e-9);
    const events: [string, number, Float32Array | null][] = [];
    if (!this.inSpeech && db > THRESH_DB) {
      this.inSpeech = true;
      this.quiet = 0;
      this.buf = [];
      events.push(["speech_start", this.t, null]);
    }
    if (this.inSpeech) {
      this.buf.push(x);
      this.quiet = db <= THRESH_DB ? this.quiet + n / SR : 0;
      if (this.quiet >= HANG_SEC) {
        this.inSpeech = false;
        const seg = new Float32Array(this.buf.reduce((a, b) => a + b.length, 0));
        let off = 0;
        for (const b of this.buf) {
          seg.set(b, off);
          off += b.length;
        }
        if (seg.length / SR - HANG_SEC >= MIN_SPEECH) events.push(["speech_end", this.t, seg]);
      }
    }
    this.t += n / SR;
    return events;
  }
}

const server = createServer((req, res) => sendJson(res, 404, { detail: "WebSocket만 받아요" }));
serveWs(server, "/ws/stt", (ws) => {
  const ep = new Endpointer();
  ws.onmessage = (data, isBinary) => {
    if (isBinary) {
      for (const [kind, t, seg] of ep.feed(data)) {
        ws.send(JSON.stringify({ type: kind, t: Math.round(t * 100) / 100 }));
        if (kind === "speech_end" && seg) ws.send(JSON.stringify({ type: "final", text: hear(seg) }));
      }
    } else if (data.toString() === "END") {
      ws.send(JSON.stringify({ type: "done" }));
      ws.close();
    }
  };
});

function pcmFrames(y: Float32Array): Uint8Array[] {
  const pcm = Buffer.alloc(y.length * 2);
  for (let i = 0; i < y.length; i++) pcm.writeInt16LE(Math.round(Math.max(-1, Math.min(1, y[i])) * 32767), i * 2);
  const out: Uint8Array[] = [];
  for (let i = 0; i + FRAME * 2 <= pcm.length; i += FRAME * 2) out.push(pcm.subarray(i, i + FRAME * 2));
  return out;
}

async function main(): Promise<void> {
  const host = await listen(server);
  const parts = [new Float32Array(0.4 * SR), say(["진료", "예약"]), new Float32Array(SR), say(["비용"]), new Float32Array(SR)]; // 말 두 마디
  const call = new Float32Array(parts.reduce((a, p) => a + p.length, 0));
  let off = 0;
  for (const p of parts) {
    call.set(p, off);
    off += p.length;
  }
  const ws = await wsConnect(host, "/ws/stt");
  const events: { type: string; t?: number; text?: string }[] = [];
  const done = new Promise<void>((resolve) => {
    ws.onmessage = (e) => {
      const m = JSON.parse(String(e.data));
      events.push(m);
      if (m.type === "done") resolve();
    };
  });
  for (const f of pcmFrames(call)) ws.send(f); // 실제로는 20 ms마다 보내지만 시험은 빠르게
  ws.send("END");
  await done;
  const finals = events.filter((m) => m.type === "final").map((m) => m.text);
  const starts = events.filter((m) => m.type === "speech_start").map((m) => m.t as number);
  console.log("받은 메시지:", events.map((m) => m.type).join(", "));
  console.log("말 시작 시각:", starts, "· 받아쓰기:", finals);
  check(finals.join("|") === "진료 예약|비용", "말 두 마디가 각각 final로 와야 해요.");
  check(starts.length === 2 && Math.abs(starts[0] - 0.4) < 0.05, "말 시작은 0.4초 근처에서 잡혀야 해요.");
  ws.close();
  console.log("서버 종료:", await closeServer(server));
}

main();

endpoint.python:
# D31 · Part 5 · 엔드포인트 명세 찾기 — 단독 실행 완성 코드 (Python 3.11)
# pip install fastapi==0.165.0 uvicorn==0.54.0 httpx==0.28.1 python-multipart==0.0.34 websockets==17.4 pydantic==2.14.4 numpy==2.4.6 soundfile==0.14.0
# 실행: python d31_endpoint.py   (서버는 임시 포트로 띄우고 스스로 요청한 뒤 종료 · 인터넷·GPU 불필요)
#   서버가 스스로 알려 주는 명세(/openapi.json · /docs)에서 경로 · 메서드 · 성공 코드를 읽어 표로 만들기 (WebSocket은 따로)
import asyncio
import io
import socket
import threading
import time

import httpx
import numpy as np
import soundfile as sf
import uvicorn
from fastapi import FastAPI, File, UploadFile, WebSocket
from fastapi.responses import Response
from pydantic import BaseModel, Field

SR = 16000
WORDS = {"진료": 500.0, "주차": 700.0, "비용": 900.0, "예약": 1100.0}
# 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def say(words, gap: float = 0.15) -> np.ndarray:
    """단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼."""
    t = np.arange(int(0.25 * SR)) / SR
    parts = []
    for w in words:
        parts += [0.4 * np.sin(2 * np.pi * WORDS[w] * t), np.zeros(int(gap * SR))]
    return np.concatenate(parts).astype(np.float32)


def speak(text: str) -> np.ndarray:
    """글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다."""
    return say(sorted((w for w in WORDS if w in text), key=text.find) or ["예약"])


def hear(y: np.ndarray) -> str:
    """소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 센 주파수로 단어를 고른다."""
    n = SR // 50
    loud = [float(np.sqrt(np.mean(y[i:i + n] ** 2))) > 0.05 for i in range(0, len(y) - n + 1, n)]
    words, start = [], None
    for k, v in enumerate(loud + [False]):
        if v and start is None:
            start = k
        elif not v and start is not None:
            seg = y[start * n:k * n]
            f = np.fft.rfftfreq(len(seg), 1 / SR)[int(np.argmax(np.abs(np.fft.rfft(seg))))]
            words.append(min(WORDS, key=lambda w: abs(WORDS[w] - f)))
            start = None
    return " ".join(words)


def wav_bytes(y: np.ndarray) -> bytes:
    buf = io.BytesIO()
    sf.write(buf, np.clip(y, -1, 1), SR, format="WAV", subtype="PCM_16")
    return buf.getvalue()

def start_server(app):
    """임시 포트(0번)를 운영체제에서 받아 uvicorn을 스레드로 띄운다 → (server, thread, 주소)."""
    sock = socket.socket()
    sock.bind(("127.0.0.1", 0))
    sock.listen()
    server = uvicorn.Server(uvicorn.Config(app, log_level="warning"))
    th = threading.Thread(target=server.run, kwargs={"sockets": [sock]}, daemon=True)
    th.start()
    while not server.started:
        time.sleep(0.02)
    return server, th, f"127.0.0.1:{sock.getsockname()[1]}"


def stop_server(server, th) -> bool:
    server.should_exit = True
    th.join(timeout=5)
    return not th.is_alive()

app = FastAPI(title="한빛치과 음성 API(모의)", version="0.31")


class TTSRequest(BaseModel):
    text: str = Field(..., min_length=1, max_length=300)


@app.get("/health", summary="서버 상태")
async def health():
    return {"ok": True}


@app.post("/tts", summary="글자 → 소리 (WAV)")
async def tts_endpoint(req: TTSRequest):
    return Response(content=wav_bytes(speak(req.text)), media_type="audio/wav")


@app.post("/stt", summary="소리 파일 → 글자")
async def stt_endpoint(file: UploadFile = File(...)):
    return {"text": hear(sf.read(io.BytesIO(await file.read()), dtype="float32")[0])}


@app.post("/jobs/stt", status_code=202, summary="긴 파일 받아쓰기 접수")
async def submit_job(file: UploadFile = File(...)):
    return {"job_id": "job-0001"}


@app.websocket("/ws/stt")
async def ws_stt(ws: WebSocket):
    await ws.accept()
    await ws.close()


async def main() -> None:
    server, th, host = start_server(app)
    async with httpx.AsyncClient(base_url=f"http://{host}", timeout=30) as c:
        spec = (await c.get("/openapi.json")).json()
        docs = await c.get("/docs")
    rows = []
    for path, ops in spec["paths"].items():
        for method, op in ops.items():
            body = ", ".join(op.get("requestBody", {}).get("content", {})) or "-"
            ok = ", ".join(k for k in op["responses"] if k.startswith("2"))
            rows.append((method.upper(), path, op.get("summary", ""), body, ok))
    rows += [("WS", r.path, "실시간 받아쓰기", "binary PCM16 20 ms", "101") for r in app.routes if r.__class__.__name__ == "APIWebSocketRoute"]
    for r in rows:
        print(f"{r[0]:<5}{r[1]:<12}{r[2]:<22}{r[3]:<32}{r[4]}")
    print("API 이름:", spec["info"]["title"], "· /docs 상태:", docs.status_code)
    got = {(r[0], r[1]) for r in rows}
    check(got == {("GET", "/health"), ("POST", "/tts"), ("POST", "/stt"), ("POST", "/jobs/stt"), ("WS", "/ws/stt")}, "경로와 메서드 5개가 명세에 나와야 해요.")
    check(docs.status_code == 200 and any(r[1] == "/jobs/stt" and r[4] == "202" for r in rows), "자동 문서(/docs)가 열리고 접수 엔드포인트의 성공 코드는 202예요.")
    print("서버 종료:", stop_server(server, th))


asyncio.run(main())

