#   엔드포인트 · 요청 검사 · 소리 응답 · 파일 업로드 · 작업 큐 · WebSocket을 정리표 순서대로 한 번씩 확인
import base64
import io

import numpy as np
import soundfile as sf
from fastapi import BackgroundTasks, FastAPI, File, UploadFile, WebSocket
from fastapi.responses import Response
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

SR = 16000
WORDS = {"진료": 500.0, "주차": 700.0, "비용": 900.0, "예약": 1100.0}
# 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def say(words, gap: float = 0.15) -> np.ndarray:
    """단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼."""
    t = np.arange(int(0.25 * SR)) / SR
    parts = []
    for w in words:
        parts += [0.4 * np.sin(2 * np.pi * WORDS[w] * t), np.zeros(int(gap * SR))]
    return np.concatenate(parts).astype(np.float32)


def speak(text: str) -> np.ndarray:
    """글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다."""
    return say(sorted((w for w in WORDS if w in text), key=text.find) or ["예약"])


def hear(y: np.ndarray) -> str:
    """소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 센 주파수로 단어를 고른다."""
    n = SR // 50
    loud = [float(np.sqrt(np.mean(y[i:i + n] ** 2))) > 0.05 for i in range(0, len(y) - n + 1, n)]
    words, start = [], None
    for k, v in enumerate(loud + [False]):
        if v and start is None:
            start = k
        elif not v and start is not None:
            seg = y[start * n:k * n]
            f = np.fft.rfftfreq(len(seg), 1 / SR)[int(np.argmax(np.abs(np.fft.rfft(seg))))]
            words.append(min(WORDS, key=lambda w: abs(WORDS[w] - f)))
            start = None
    return " ".join(words)


def wav_bytes(y: np.ndarray) -> bytes:
    buf = io.BytesIO()
    sf.write(buf, np.clip(y, -1, 1), SR, format="WAV", subtype="PCM_16")
    return buf.getvalue()

app = FastAPI()
JOBS = {}


class TTSRequest(BaseModel):
    text: str = Field(..., min_length=1, max_length=300)


@app.get("/health")                                # 엔드포인트: 주소 + 처리 함수
def health():
    return {"ok": True}


@app.post("/tts")                                  # 소리 응답: 바이트 + content-type
def tts(req: TTSRequest):
    return Response(content=wav_bytes(speak(req.text)), media_type="audio/wav")


@app.post("/stt")                                  # 파일 업로드: UploadFile = File(...)
async def stt(file: UploadFile = File(...)):
    return {"text": hear(sf.read(io.BytesIO(await file.read()), dtype="float32")[0])}


@app.post("/jobs/stt", status_code=202)            # 작업 큐: 접수증 먼저
def job(background: BackgroundTasks, file: UploadFile = File(...)):
    data = file.file.read()
    JOBS["job-1"] = {"status": "queued"}
    background.add_task(lambda: JOBS.update({"job-1": {"status": "done", "text": hear(sf.read(io.BytesIO(data), dtype="float32")[0])}}))
    return {"poll": "/jobs/job-1"}


@app.get("/jobs/{job_id}")
def get_job(job_id: str):
    return JOBS[job_id]


@app.websocket("/ws/echo")                         # WebSocket: 한 연결로 계속 주고받기
async def ws_echo(ws: WebSocket):
    await ws.accept()
    await ws.send_json({"len": len(await ws.receive_bytes())})
    await ws.close()


c = TestClient(app)
wav = wav_bytes(say(["진료"]))
rows = [
    ("GET /health", c.get("/health").status_code, 200),
    ("POST /tts (빈 글자)", c.post("/tts", json={"text": ""}).status_code, 422),
    ("POST /stt (정상 WAV)", c.post("/stt", files={"file": ("a.wav", wav, "audio/wav")}).status_code, 200),
    ("POST /jobs/stt", c.post("/jobs/stt", files={"file": ("a.wav", wav, "audio/wav")}).status_code, 202),
]
for name, got, want in rows:
    print(f"{name:<44}{got} (기대 {want})")
check(all(g == w for _, g, w in rows), "정리표의 상태 코드와 같아야 해요.")

r = c.post("/tts", json={"text": "예약"})
check(r.headers["content-type"] == "audio/wav" and hear(sf.read(io.BytesIO(r.content), dtype="float32")[0]) == "예약", "소리 응답은 바이트와 audio/wav예요.")
check(c.post("/stt", files={"file": ("a.wav", wav, "audio/wav")}).json()["text"] == "진료", "업로드한 파일을 받아쓰기해요.")
check(c.get("/jobs/job-1").json() == {"status": "done", "text": "진료"}, "접수한 작업은 응답 뒤에 끝나 조회하면 done이에요.")

ratio = len(base64.b64encode(wav)) / len(wav)
print(f"JSON 안에 base64로 넣으면 크기가 {ratio:.2f}배 (이론 4/3 = {4 / 3:.2f})")
check(abs(ratio - 4 / 3) < 0.01, "base64는 바이트를 글자로 바꾸느라 약 4/3배 커져요.")
with c.websocket_connect("/ws/echo") as ws:
    ws.send_bytes(b"\0" * 640)
    check(ws.receive_json() == {"len": 640}, "WebSocket은 한 연결로 20 ms 조각(640바이트)을 계속 보낼 수 있어요.")

