}

type Reply = { status: number; type: string; body: unknown };
const JOBS: Record<string, { status: string; text?: string }> = {};

// 서버 없이 '주소 → 응답'만 돌려 보는 작은 라우터 (대체 경로: 실제 HTTP 대신 함수 호출)
function handle(method: string, path: string, payload?: { json?: { text?: string }; wav?: Buffer; type?: string }): Reply {
  if (method === "GET" && path === "/health") return { status: 200, type: "application/json", body: { ok: true } };
  if (method === "POST" && path === "/tts") {
    const t = payload?.json?.text;
    if (typeof t !== "string" || t.length < 1 || t.length > 300) return { status: 422, type: "application/json", body: { detail: "text 1~300자" } };
    return { status: 200, type: "audio/wav", body: wavBytes(speak(t)) };
  }
  if (method === "POST" && path === "/stt") {
    if (!payload?.wav) return { status: 422, type: "application/json", body: { detail: "file 칸 없음" } };
    return { status: 200, type: "application/json", body: { text: hear(decodeWav(payload.wav)) } };
  }
  if (method === "POST" && path === "/jobs/stt") {
    JOBS["job-1"] = { status: "queued" };
    const wav = payload?.wav as Buffer;
    setImmediate(() => (JOBS["job-1"] = { status: "done", text: hear(decodeWav(wav)) })); // 응답을 보낸 '뒤에' 실행
    return { status: 202, type: "application/json", body: { poll: "/jobs/job-1" } };
  }
  if (method === "GET" && path === "/jobs/job-1") return { status: 200, type: "application/json", body: JOBS["job-1"] };
  return { status: 404, type: "application/json", body: {} };
}

async function main(): Promise<void> {
  const wav = wavBytes(say(["진료"]));
  const rows: [string, number, number][] = [
    ["GET /health", handle("GET", "/health").status, 200],
    ["POST /tts (빈 글자)", handle("POST", "/tts", { json: { text: "" } }).status, 422],
    ["POST /stt (정상 WAV)", handle("POST", "/stt", { wav }).status, 200],
    ["POST /jobs/stt", handle("POST", "/jobs/stt", { wav }).status, 202],
  ];
  for (const [name, got, want] of rows) console.log(`${name.padEnd(24)}${got} (기대 ${want})`);
  check(rows.every(([, g, w]) => g === w), "정리표의 상태 코드와 같아야 해요.");

  const tts = handle("POST", "/tts", { json: { text: "예약" } });
  check(tts.type === "audio/wav" && hear(decodeWav(tts.body as Buffer)) === "예약", "소리 응답은 바이트와 audio/wav예요.");
  check((handle("POST", "/stt", { wav }).body as { text: string }).text === "진료", "업로드한 파일을 받아쓰기해요.");
  await new Promise((r) => setImmediate(r));
  check((handle("GET", "/jobs/job-1").body as { status: string }).status === "done", "접수한 작업은 응답 뒤에 끝나 조회하면 done이에요.");

  const ratio = wav.toString("base64").length / wav.length;
  console.log(`JSON 안에 base64로 넣으면 크기가 ${ratio.toFixed(2)}배 (이론 4/3 = ${(4 / 3).toFixed(2)})`);
  check(Math.abs(ratio - 4 / 3) < 0.01, "base64는 바이트를 글자로 바꾸느라 약 4/3배 커져요.");
  check(new Int16Array(320).byteLength === 640, "20 ms 조각 하나는 320 샘플 = 640바이트예요.");
}

main();
